import{c as d,Q as a,j as r,m as e}from"./chunks/framework.BPKcPtvA.js";const o="/images/class-auIJjfbtsBwqBdw.jpg",u=JSON.parse('{"title":"进阶职业（二转/三转）全览","description":"RO3进阶职业系统介绍，涵盖骑士、猎人、巫师、刺客十字等二转及更高阶职业的转职条件与特点。","frontmatter":{"title":"进阶职业（二转/三转）全览","description":"RO3进阶职业系统介绍，涵盖骑士、猎人、巫师、刺客十字等二转及更高阶职业的转职条件与特点。","lastUpdated":true},"headers":[],"relativePath":"jobs/advanced.md","filePath":"jobs/advanced.md","lastUpdated":1780230058000}'),h={name:"jobs/advanced.md"};function n(s,t,i,l,b,g){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="进阶职业-二转-三转-全览" tabindex="-1">进阶职业（二转/三转）全览 <a class="header-anchor" href="#进阶职业-二转-三转-全览" aria-label="Permalink to &quot;进阶职业（二转/三转）全览&quot;">​</a></h1><p>RO3延续了RO经典的转职体系，在达到一定等级后可以进行转职，解锁更强大的职业技能和玩法。</p><p><img src="'+o+'" alt="RO3 职业群像"></p><h2 id="转职体系概览" tabindex="-1">转职体系概览 <a class="header-anchor" href="#转职体系概览" aria-label="Permalink to &quot;转职体系概览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>等级要求</th><th>说明</th></tr></thead><tbody><tr><td>初心者 (Novice)</td><td>Lv.1</td><td>初始状态</td></tr><tr><td>一转 (First Job)</td><td>Lv.10+</td><td>选择六大基础职业</td></tr><tr><td>二转 (Second Job)</td><td>Lv.50</td><td>进阶职业，解锁核心技能</td></tr><tr><td>三转 (Third Job)</td><td>Lv.80+</td><td>高阶职业，终极技能</td></tr></tbody></table><blockquote><p>以上等级要求基于RO系列传统设定和Pioneer Test信息，具体以正式服为准。</p></blockquote><h2 id="二转职业一览" tabindex="-1">二转职业一览 <a class="header-anchor" href="#二转职业一览" aria-label="Permalink to &quot;二转职业一览&quot;">​</a></h2><h3 id="剑士系" tabindex="-1">剑士系 <a class="header-anchor" href="#剑士系" aria-label="Permalink to &quot;剑士系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>剑士 (Swordman)</td><td><strong>骑士 (Knight)</strong></td><td>骑乘战斗、高生命、范围攻击（骑兵修炼、反击、连刺攻击）</td></tr><tr><td>剑士 (Swordman)</td><td><strong>十字军 (Crusader)</strong></td><td>防御型、圣属性攻击、团队保护（盾技、圣十字审判、牺牲）</td></tr></tbody></table><h3 id="法师系" tabindex="-1">法师系 <a class="header-anchor" href="#法师系" aria-label="Permalink to &quot;法师系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>法师 (Mage)</td><td><strong>巫师 (Wizard)</strong></td><td>元素魔法专精、大范围AOE（暴风雪、陨石术、怒雷强击）</td></tr><tr><td>法师 (Mage)</td><td><strong>贤者 (Sage)</strong></td><td>属性转换、地属性魔法、魔法取消（地领、水领、火领、风领）</td></tr></tbody></table><h3 id="弓箭手系" tabindex="-1">弓箭手系 <a class="header-anchor" href="#弓箭手系" aria-label="Permalink to &quot;弓箭手系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>弓箭手 (Archer)</td><td><strong>猎人 (Hunter)</strong></td><td>远程物理DPS、陷阱战术（闪电冲击、猎鹰突击、定位陷阱）</td></tr><tr><td>弓箭手 (Archer)</td><td><strong>吟游诗人/舞娘 (Bard/Dancer)</strong></td><td>辅助演奏、团队增益（布莱奇之诗、战鼓震天）</td></tr></tbody></table><h3 id="服事系" tabindex="-1">服事系 <a class="header-anchor" href="#服事系" aria-label="Permalink to &quot;服事系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>服事 (Acolyte)</td><td><strong>祭司 (Priest)</strong></td><td>治疗、复活、增益（光耀之堂、圣母之祈福、沉默之术）</td></tr><tr><td>服事 (Acolyte)</td><td><strong>武道家 (Monk)</strong></td><td>近距离格斗、气功技能（阿修罗霸凰拳、真剑百破道）</td></tr></tbody></table><h3 id="盗贼系" tabindex="-1">盗贼系 <a class="header-anchor" href="#盗贼系" aria-label="Permalink to &quot;盗贼系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>盗贼 (Thief)</td><td><strong>刺客 (Assassin)</strong></td><td>双刀流、暴击、毒系攻击（音速投掷、心灵震波、毒液制作）</td></tr><tr><td>盗贼 (Thief)</td><td><strong>流氓 (Rogue)</strong></td><td>偷窃、伪装、抄技能（潜击、背刺、强盗之魂）</td></tr></tbody></table><h3 id="商人系" tabindex="-1">商人系 <a class="header-anchor" href="#商人系" aria-label="Permalink to &quot;商人系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>基础职业</th><th>二转职业</th><th>特点</th></tr></thead><tbody><tr><td>商人 (Merchant)</td><td><strong>铁匠 (Blacksmith)</strong></td><td>武器制作、精炼加成、大地之击（武器研究、速度激发、凶砍）</td></tr><tr><td>商人 (Merchant)</td><td><strong>炼金术士 (Alchemist)</strong></td><td>药水制作、生物召唤、扔瓶子（药水投掷、火烟瓶投掷、召唤生命体）</td></tr></tbody></table><h2 id="三转职业预告" tabindex="-1">三转职业预告 <a class="header-anchor" href="#三转职业预告" aria-label="Permalink to &quot;三转职业预告&quot;">​</a></h2><p>根据实机预告片和官方信息，RO3将包含以下三转职业（暂定名称）：</p><table tabindex="0"><thead><tr><th>二转职业</th><th>三转职业</th><th>实机演示确认</th></tr></thead><tbody><tr><td>骑士</td><td><strong>骑士领主 (Lord Knight)</strong></td><td>✅ 预告片中出现</td></tr><tr><td>巫师</td><td><strong>大法师 (High Wizard)</strong></td><td>✅ 预告片中出现</td></tr><tr><td>刺客</td><td><strong>十字刺客 (Assassin Cross)</strong></td><td>✅ 预告片中出现</td></tr><tr><td>猎人</td><td><strong>神射手 (Sniper)</strong></td><td>预计包含</td></tr><tr><td>祭司</td><td><strong>大主教 (High Priest)</strong></td><td>✅ Bilibili实机有出现</td></tr><tr><td>铁匠</td><td><strong>神工匠 (Whitesmith)</strong></td><td>预计包含</td></tr></tbody></table><h2 id="转职建议" tabindex="-1">转职建议 <a class="header-anchor" href="#转职建议" aria-label="Permalink to &quot;转职建议&quot;">​</a></h2><h3 id="新手推荐转职路径" tabindex="-1">新手推荐转职路径 <a class="header-anchor" href="#新手推荐转职路径" aria-label="Permalink to &quot;新手推荐转职路径&quot;">​</a></h3><ul><li><strong>F2P玩家</strong>：剑士→骑士（坦克好组队）或服事→祭司（治疗必备）</li><li><strong>微氪玩家</strong>：法师→巫师（AOE刷怪效率高）</li><li><strong>独狼玩家</strong>：弓箭手→猎人（远程安全输出）</li></ul><h3 id="二转转职准备" tabindex="-1">二转转职准备 <a class="header-anchor" href="#二转转职准备" aria-label="Permalink to &quot;二转转职准备&quot;">​</a></h3><ol><li><strong>等级达标</strong>：建议达到Lv.50+再转职，保留足够的技能点</li><li><strong>装备准备</strong>：提前准备转职后所需的武器和防具</li><li><strong>材料收集</strong>：部分转职需要收集特定道具或完成任务</li><li><strong>资金储备</strong>：准备至少50,000 Zeny用于转职相关开销</li></ol><p>更多详细的二转职业技能搭配和配装推荐，将在后续更新中逐步完善，敬请期待！</p>',28)])])}const m=d(h,[["render",n]]);export{u as __pageData,m as default};
